  "settings.label.ui.showResponseTokensPerSecond": "\u663E\u793A\u56DE\u590D Tokens/\u79D2",
  "settings.label.ui.accessibility.enableLoadingPhrases": "\u542F\u7528\u52A0\u8F7D\u6587\u6848",
  "settings.description.ui.accessibility.enableLoadingPhrases": "\u663E\u793A\u8F6E\u6362\u52A0\u8F7D\u6587\u6848\u3002\u5173\u95ED\u540E\u9690\u85CF\u5185\u7F6E\u53CA\u5BBF\u4E3B\u63D0\u4F9B\u7684\u6587\u6848\u3002",
  "settings.description.ui.showResponseTokensPerSecond": "\u6A21\u578B\u6D41\u5F0F\u8F93\u51FA\u65F6\uFF0C\u5728\u56DE\u590D token \u8BA1\u6570\u65C1\u663E\u793A\u5B9E\u65F6\u7684 tokens/\u79D2\u4F30\u503C\u3002\u4E0B\u4E2A\u4F1A\u8BDD\u751F\u6548\u3002",
  "settings.label.ui.showToolCallDetails": "\u663E\u793A\u5DE5\u5177\u8C03\u7528\u8BE6\u60C5",
  "settings.description.ui.showToolCallDetails": "\u5185\u8054\u663E\u793A\u5DE5\u5177\u7684\u53C2\u6570\u548C\u7ED3\u679C\u3002\u5173\u95ED\u540E\u666E\u901A\u5DE5\u5177\u8C03\u7528\u6E32\u67D3\u4E3A\u5355\u884C\u6458\u8981\uFF1B\u5728\u865A\u62DF\u5316\u5386\u53F2\u4E2D\u70B9\u51FB\u6458\u8981\u6216\u6309 Ctrl+O \u53EF\u5C55\u5F00\u8BE6\u60C5\u3002\u5BA1\u6279\u63D0\u793A\u3001\u7528\u6237\u4E3B\u52A8\u53D1\u8D77\u7684 shell \u547D\u4EE4\u548C\u83B7\u5F97\u7126\u70B9\u7684\u4EA4\u4E92\u5F0F shell \u4FDD\u6301\u5C55\u5F00\u3002",
  "settings.label.privacy.usageStatisticsEnabled": "\u542F\u7528\u4F7F\u7528\u7EDF\u8BA1",
  "settings.description.privacy.usageStatisticsEnabled": "\u542F\u7528\u4F7F\u7528\u7EDF\u8BA1\u6536\u96C6\u3002",
  "settings.label.fastModel": "\u5FEB\u901F\u6A21\u578B",
  "settings.description.fastModel": "\u7528\u4E8E\u751F\u6210\u63D0\u793A\u5EFA\u8BAE\u548C\u63A8\u6D4B\u6267\u884C\u7684\u6A21\u578B\u3002\u7559\u7A7A\u5219\u4F7F\u7528\u4E3B\u6A21\u578B\u3002\u8F83\u5C0F/\u66F4\u5FEB\u7684\u6A21\u578B\uFF08\u4F8B\u5982 qwen3-coder-flash\uFF09\u53EF\u4EE5\u964D\u4F4E\u5EF6\u8FDF\u548C\u6210\u672C\u3002",
